"use strict";(self.webpackChunkwiki_es=self.webpackChunkwiki_es||[]).push([["59833"],{26954(e){e.exports=JSON.parse('{"tag":{"label":"Rob\xf3tica","permalink":"/es/tags/robotica","allTagsPath":"/es/tags","count":4,"items":[{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J50/es_reComputer_Robotics_J501_Getting_Started","title":"Flashear Jetpack && Uso de interfaces","description":"Este wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y al uso de las interfaces de la placa portadora reComputer Jetson Robotics J501. Cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar varias interfaces como ranuras duales M.2 Key M, Ethernet 10GbE + 4x 1GbE, USB 3.0, cuatro interfaces CAN (2 nativas + 2 SPI-a-CAN), UART, DI/DO, I2S y expansi\xf3n de c\xe1mara GMSL2, ayudando a los usuarios a comenzar r\xe1pidamente con el desarrollo de rob\xf3tica en la plataforma J501.","permalink":"/es/ai_robotics_recomputer_j501_robotics_getting_started"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/es_reComputer_Robotics_Getting_Started","title":"Introducci\xf3n a reComputer Robotics","description":"La reComputer Robotics J401 es una placa portadora de IA de borde de alto rendimiento dise\xf1ada para aplicaciones avanzadas de rob\xf3tica. Es compatible con los m\xf3dulos NVIDIA Jetson Orin Nano y Orin NX en modo Super/MAXN, ofreciendo hasta 157 TOPS de potencia de c\xf3mputo de IA. La placa ofrece amplias opciones de conectividad, incluyendo Ethernet Gigabit dual, m\xfaltiples puertos USB 3.2, CAN, ranuras M.2 para m\xf3dulos 5G/Wi\u2011Fi/BT y compatibilidad opcional con c\xe1maras GMSL2. Con JetPack 6 preinstalado, garantiza un despliegue fluido para el desarrollo de rob\xf3tica. El dise\xf1o robusto admite un amplio rango de temperaturas de funcionamiento e incluye un disipador de calor con ventilador preinstalado. La configuraci\xf3n implica flashear el sistema operativo JetPack en un SSD NVMe usando un PC host Ubuntu compatible, seguido de la configuraci\xf3n del hardware y el uso de las interfaces. Se proporcionan especificaciones detalladas de hardware, dibujos mec\xe1nicos y recursos t\xe9cnicos para desarrolladores, junto con canales de soporte t\xe9cnico y de comunidad para resoluci\xf3n de problemas y discusi\xf3n.","permalink":"/es/recomputer_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/J501_Mini/es_Robotics_J501_Mini_Hardware_Interfaces_Usage","title":"Mini J501 Flashear JetPack y Uso de Interfaces","description":"Este wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y al uso de las interfaces de la placa carrier Jetson Mini J501. Dise\xf1ada para escenarios de IA en el borde y rob\xf3tica, cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar interfaces como M.2, Ethernet, USB, CAN, UART, DI/DO, I2S y expansi\xf3n de c\xe1mara GMSL2.","permalink":"/es/recomputer_j501_mini_getting_started"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/es_Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"Uso de interfaces","description":"Este wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y al uso de las interfaces de la carrier board reComputer Jetson Robotics J401. Cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar varias interfaces como M.2, Ethernet, USB, CAN, UART, I2C y expansi\xf3n de c\xe1mara GMSL2, ayudando a los usuarios a comenzar r\xe1pidamente con el desarrollo de rob\xf3tica en la plataforma J401.","permalink":"/es/recomputer_jetson_robotics_j401_getting_started"}],"unlisted":false}}')}}]);